def solve_v8(grid_in):
    """Only draw V-line cross if there's another V-line hitting the same block"""
    grid = [row[:] for row in grid_in]
    h, w = len(grid), len(grid[0])

    # Find blocks
    block_regions = []
    for r in range(h - 2):
        for c in range(w - 2):
            top_ok = (grid[r][c] == 3 and grid[r][c+1] == 3 and grid[r][c+2] == 3)
            mid_ok = (grid[r+1][c] == 3 and grid[r+1][c+1] == 2 and grid[r+1][c+2] == 3)
            bot_ok = (grid[r+2][c] == 3 and grid[r+2][c+1] == 3 and grid[r+2][c+2] == 3)
            if top_ok and mid_ok and bot_ok:
                br, bc = r+1, c+1
                block_regions.append((br, bc))

    horizontal_lines = [r for r in range(h) if all(grid[r][c] == 2 for c in range(w))]
    vertical_lines = [c for c in range(w) if sum(1 for r in range(h) if grid[r][c] == 2) >= h * 0.8]

    def place_cross_from_horizontal_line(r_line, bc_col, h, w, max_ext=3):
        for dr in range(-max_ext, max_ext+1):
            abs_dr = abs(dr)
            if abs_dr == 0:
                for dc in [-1, 1]:
                    r, c = r_line + dr, bc_col + dc
                    if 0 <= r < h and 0 <= c < w and grid[r][c] != 3:
                        grid[r][c] = 1
            elif abs_dr == 1:
                for dc in [-1, 0, 1]:
                    r, c = r_line + dr, bc_col + dc
                    if 0 <= r < h and 0 <= c < w and grid[r][c] != 3:
                        grid[r][c] = 1
            else:
                r, c = r_line + dr, bc_col
                if 0 <= r < h and 0 <= c < w and grid[r][c] != 3:
                    grid[r][c] = 1

    # Count how many V-lines hit each block
    block_vline_hits = {}
    for br, bc in block_regions:
        bbc_start, bbc_end = bc - 1, bc + 1
        hits = []
        for c in vertical_lines:
            if bbc_start <= c <= bbc_end:
                hits.append(c)
        block_vline_hits[(br, bc)] = hits

    # For Demo 2: block1 has [3,9], block2 has [3,9]
    print(f"V-line hits per block: {block_vline_hits}")

    for br, bc in block_regions:
        for r_line in horizontal_lines:
            place_cross_from_horizontal_line(r_line, bc, h, w)

        # For V-lines, only fill rows where ANOTHER V-line also exists
        for bbr, bbc in block_regions:
            if bbr == br and bc == bbc:
                continue  # Skip self

            bbc_start, bbc_end = bbc - 1, bbc + 1
            v_hit_other = any(bbc_start <= c <= bbc_end for c in block_vline_hits[bbr])

            if v_hit_other:
                # This block was also hit by the other V-line
                # Fill its rows except block area
                for r in range(br - 1, br + 2):
                    if 0 <= r < h:
                        for c in range(w):
                            if c < bc - 1 or c > bc + 1:
                                if grid[r][c] != 2:
                                    grid[r][c] = 1

    return grid

