# Based on demo 1 analysis, the pattern fills cells between block edges and V-lines
# For each row containing a block, fill horizontally between block ends and adjacent V-lines

def solve_with_fill(grid_in):
    grid = [row[:] for row in grid_in]
    h, w = len(grid), len(grid[0])

    # Find blocks and their boundaries
    blocks = []  # [(r, c_left, c_right)]
    for r in range(h - 2):
        for c in range(w - 2):
            top_ok = grid[r][c] == 3 and grid[r][c+1] == 3 and grid[r][c+2] == 3
            mid_ok = grid[r+1][c] == 3 and grid[r+1][c+1] == 2 and grid[r+1][c+2] == 3
            bot_ok = grid[r+2][c] == 3 and grid[r+2][c+1] == 3 and grid[r+2][c+2] == 3
            if top_ok and mid_ok and bot_ok:
                blocks.append((r+1, c, c+2))  # (center_row, left_col, right_col)

    v_lines = sorted([c for c in range(w) if sum(1 for r in range(h) if grid[r][c] == 2) >= h * 0.8])

    # Fill rows that contain blocks
    for br, cl, cr in blocks:
        # Look at all V-lines and fill between them appropriately
        for i in range(len(v_lines) - 1):
            v1, v2 = v_lines[i], v_lines[i+1]

            # Left side of first V-line
            if v1 > cl:
                for c in range(cl, v1):
                    if grid[br][c] not in (2, 3):
                        grid[br][c] = 1

            # Between V-lines
            if cr < v1:
                for c in range(cr + 1, v1):
                    if grid[br][c] not in (2, 3):
                        grid[br][c] = 1

            # Right side of second V-line
            if v2 < w and not v2 == 17:  # avoid going past grid
                for c in range(max(v2 + 1, cr + 1), min(w, v2 + 4)):
                    pass  # Don't fill too far

